--
-- Table structure for table `blocks`
--

DROP TABLE IF EXISTS `blocks`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `blocks` (
  `height` int(11) NOT NULL COMMENT '区块高度',
  `hash` char(64) NOT NULL COMMENT '区块哈希',
  `prev_hash` char(64) NOT NULL COMMENT '前一块哈希',
  `merkle_root` char(64) NOT NULL COMMENT '交易 Merkle 根',
  `ts` bigint(20) NOT NULL COMMENT '出块时间戳(ms)',
  `nonce` bigint(20) NOT NULL COMMENT '工作量证明随机数',
  `difficulty` tinyint(4) NOT NULL DEFAULT '4' COMMENT '难度（前导 0 个数）',
  `miner` char(32) NOT NULL COMMENT '出块者（本平台为系统铸币账户）',
  `tx_count` int(11) NOT NULL DEFAULT '0' COMMENT '交易笔数',
  `mined_ms` int(11) NOT NULL DEFAULT '0' COMMENT '本块挖矿耗时(ms)',
  `size_bytes` int(11) NOT NULL DEFAULT '0' COMMENT '区块字节数',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`height`),
  UNIQUE KEY `uk_hash` (`hash`),
  KEY `idx_blk_ts` (`ts`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='区块表（哈希链）';
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `blocks`
--

LOCK TABLES `blocks` WRITE;
