--
-- Table structure for table `checkins`
--

DROP TABLE IF EXISTS `checkins`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `checkins` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `user_id` bigint(20) unsigned NOT NULL COMMENT '用户ID',
  `day` date NOT NULL COMMENT '签到日期',
  `base_points` int(11) NOT NULL DEFAULT '0' COMMENT '基础分',
  `bonus_points` int(11) NOT NULL DEFAULT '0' COMMENT '连续加成',
  `streak_after` int(11) NOT NULL DEFAULT '1' COMMENT '签到后的连续天数',
  `total_points` int(11) NOT NULL DEFAULT '0' COMMENT '本次总得分 = base + bonus',
  `late_flag` tinyint(4) NOT NULL DEFAULT '0' COMMENT '是否深夜补签(23:00后)',
  `ip` varchar(45) DEFAULT NULL COMMENT '来源IP（风控用）',
  `device` varchar(60) DEFAULT NULL COMMENT '设备指纹（风控用）',
  `txid` char(64) DEFAULT NULL COMMENT '链上交易号',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_user_day` (`user_id`,`day`),
  KEY `idx_day` (`day`),
  KEY `idx_txid` (`txid`),
  CONSTRAINT `fk_ck_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=1507 DEFAULT CHARSET=utf8mb4 COMMENT='每日签到记录';
/*!40101 SET character_set_client = @saved_cs_client */;

