--
-- Table structure for table `point_accounts`
--

DROP TABLE IF EXISTS `point_accounts`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `point_accounts` (
  `addr` char(32) NOT NULL COMMENT '链上地址',
  `user_id` bigint(20) unsigned DEFAULT NULL COMMENT '关联用户（系统账户为 NULL）',
  `label` varchar(40) NOT NULL COMMENT '账户名（系统账户如：铸币/销毁/奖池/公益）',
  `is_system` tinyint(4) NOT NULL DEFAULT '0' COMMENT '1 系统账户',
  `on_chain` bigint(20) NOT NULL DEFAULT '0' COMMENT '链上余额（按 txs 汇总）',
  `tx_count` int(11) NOT NULL DEFAULT '0' COMMENT '发生过的交易笔数',
  `first_seen` datetime DEFAULT NULL COMMENT '首次交易时间',
  `last_seen` datetime DEFAULT NULL COMMENT '最近交易时间',
  PRIMARY KEY (`addr`),
  KEY `idx_pa_user` (`user_id`),
  KEY `idx_pa_sys` (`is_system`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='积分账户表（含 4 个系统账户）';
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `point_accounts`
--

LOCK TABLES `point_accounts` WRITE;
/*!40000 ALTER TABLE `point_accounts` DISABLE KEYS */;
