--
-- Table structure for table `point_ledger`
--

DROP TABLE IF EXISTS `point_ledger`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `point_ledger` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `user_id` bigint(20) unsigned NOT NULL,
  `addr` char(32) NOT NULL COMMENT '用户的链上地址',
  `type` enum('checkin','task','daybonus','badge','redeem','donate','stake','settle','pool','burn','transfer','adjust') NOT NULL COMMENT '流水类型',
  `direction` tinyint(4) NOT NULL COMMENT '1 入账 / -1 出账',
  `amount` int(11) NOT NULL COMMENT '变动积分（正数）',
  `balance_after` int(11) NOT NULL COMMENT '变动后余额（对账用）',
  `memo` varchar(120) DEFAULT NULL,
  `ref_id` bigint(20) unsigned DEFAULT NULL COMMENT '关联业务ID（签到/任务/兑换单）',
  `txid` char(64) DEFAULT NULL COMMENT '链上交易号',
  `block_height` int(11) DEFAULT NULL COMMENT '所在区块高度',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_pl_user` (`user_id`,`created_at`),
  KEY `idx_pl_type` (`type`),
  KEY `idx_pl_txid` (`txid`),
  CONSTRAINT `fk_pl_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=4708 DEFAULT CHARSET=utf8mb4 COMMENT='积分流水表（业务账本）';
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `point_ledger`
--

LOCK TABLES `point_ledger` WRITE;
/*!40000 ALTER TABLE `point_ledger` DISABLE KEYS */;
