--
-- Table structure for table `rewards`
--

DROP TABLE IF EXISTS `rewards`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `rewards` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(60) NOT NULL COMMENT '商品名',
  `category` enum('coupon','course','goods','virtual','charity') NOT NULL COMMENT '券/课程/实物/虚拟/公益',
  `cost` int(11) NOT NULL COMMENT '所需积分',
  `stock` int(11) NOT NULL DEFAULT '0' COMMENT '库存',
  `sold` int(11) NOT NULL DEFAULT '0' COMMENT '已兑换',
  `cover_color` varchar(16) DEFAULT '#5b6cff' COMMENT '封面配色',
  `descr` varchar(160) DEFAULT NULL,
  `per_limit` int(11) NOT NULL DEFAULT '1' COMMENT '每人限兑',
  `status` tinyint(4) NOT NULL DEFAULT '1' COMMENT '1 上架 0 下架',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_rw_cat` (`category`),
  KEY `idx_rw_status` (`status`)
) ENGINE=InnoDB AUTO_INCREMENT=58 DEFAULT CHARSET=utf8mb4 COMMENT='积分商城商品表';
/*!40101 SET character_set_client = @saved_cs_client */;

