DROP TABLE IF EXISTS `task_logs`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `task_logs` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `task_id` bigint(20) unsigned NOT NULL,
  `user_id` bigint(20) unsigned NOT NULL,
  `action` enum('create','done','undo','skip','restore') NOT NULL COMMENT '动作',
  `points_delta` int(11) NOT NULL DEFAULT '0' COMMENT '本次动作导致的积分变化',
  `ip` varchar(45) DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_tl_task` (`task_id`),
  KEY `idx_tl_user` (`user_id`,`created_at`)
) ENGINE=InnoDB AUTO_INCREMENT=2617 DEFAULT CHARSET=utf8mb4 COMMENT='任务操作日志';
/*!40101 SET character_set_client = @saved_cs_client */;

