DROP TABLE IF EXISTS `teams`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `teams` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(40) NOT NULL COMMENT '自习室名称',
  `owner_id` bigint(20) unsigned NOT NULL COMMENT '房主',
  `slogan` varchar(80) DEFAULT NULL COMMENT '口号',
  `goal` varchar(80) DEFAULT NULL COMMENT '共同目标',
  `join_code` char(6) NOT NULL COMMENT '邀请码',
  `max_member` int(11) NOT NULL DEFAULT '20',
  `member_count` int(11) NOT NULL DEFAULT '0',
  `total_points` int(11) NOT NULL DEFAULT '0' COMMENT '成员积分合计',
  `checkin_rate` int(11) NOT NULL DEFAULT '0' COMMENT '今日打卡率(%)',
  `status` tinyint(4) NOT NULL DEFAULT '1',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_join_code` (`join_code`),
  KEY `idx_tm_owner` (`owner_id`)
) ENGINE=InnoDB AUTO_INCREMENT=61 DEFAULT CHARSET=utf8mb4 COMMENT='自习室（团队）表';
