DROP TABLE IF EXISTS `user_stats`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `user_stats` (
  `user_id` bigint(20) unsigned NOT NULL COMMENT '用户ID',
  `balance` int(11) NOT NULL DEFAULT '0' COMMENT '可用积分余额',
  `earned` int(11) NOT NULL DEFAULT '0' COMMENT '累计获得积分',
  `spent` int(11) NOT NULL DEFAULT '0' COMMENT '累计消耗积分',
  `frozen` int(11) NOT NULL DEFAULT '0' COMMENT '押注中的冻结积分',
  `checkin_days` int(11) NOT NULL DEFAULT '0' COMMENT '累计签到天数',
  `streak` int(11) NOT NULL DEFAULT '0' COMMENT '当前连续签到天数',
  `max_streak` int(11) NOT NULL DEFAULT '0' COMMENT '历史最长连续签到',
  `task_done` int(11) NOT NULL DEFAULT '0' COMMENT '累计完成单任务数',
  `day_clear` int(11) NOT NULL DEFAULT '0' COMMENT '累计「当天全清」次数',
  `badge_count` int(11) NOT NULL DEFAULT '0' COMMENT '持有徽章数',
  `level` tinyint(4) NOT NULL DEFAULT '1' COMMENT '等级 1~10',
  `exp` int(11) NOT NULL DEFAULT '0' COMMENT '成长值',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`user_id`),
  KEY `idx_balance` (`balance`),
  KEY `idx_streak` (`streak`),
  CONSTRAINT `fk_stats_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='用户统计表（余额/连续天数/等级）';
/*!40101 SET character_set_client = @saved_cs_client */;

